B.aiS=new A.V(B.ag,["\xbfC\xf3mo puedo cancelar mi reserva?",'Puedes cancelar desde "Mis Reservas" hasta 24 horas antes del check-in. Las cancelaciones dentro de ese plazo son gratuitas salvo que la propiedad indique lo contrario.'],t.w)
B.aj5=new A.V(B.ag,["\xbfQu\xe9 hago si tengo un problema en el alojamiento?","Contacta de inmediato con nuestro soporte 24/7. Te ayudaremos a resolver el problema o, si es necesario, te buscaremos alojamiento alternativo sin coste adicional."],t.w)
B.aiR=new A.V(B.ag,["\xbfC\xf3mo modifico las fechas de mi reserva?","Las modificaciones est\xe1n sujetas a disponibilidad. Contacta con nosotros al menos 48h antes y gestionamos el cambio de fechas sin complicaciones."],t.w)
B.aiD=new A.V(B.ag,["\xbfOfrecen garant\xeda de precio m\xe1s bajo?","S\xed. Si encuentras el mismo hotel a menor precio en otro sitio web dentro de las 24h tras reservar, te igualamos el precio sin preguntas."],t.w)
B.aiZ=new A.V(B.ag,["\xbfEs seguro pagar en SkyTrip?","Todos los pagos se procesan con cifrado SSL y cumplimos con PCI-DSS. Nunca almacenamos datos de tarjetas bancarias en nuestros servidores."],t.w)
B.a8i=s([B.aiS,B.aj5,B.aiR,B.aiD,B.aiZ],t.J)
B.aj3=new A.V(B.ag,["Explora el mundo con SkyTrip","Descubre cientos de destinos en todo el mundo. Filtra por pa\xeds y encuentra el alojamiento perfecto para cada aventura."],t.w)
B.ajg=new A.V(B.ag,["Destinos recomendados","Cada semana actualizamos nuestra selecci\xf3n de destinos m\xe1s populares con las mejores ofertas disponibles."],t.w)
B.a7r=s([B.aj3,B.ajg],t.J)
B.aiX=new A.V(B.ag,["Encuentra tu alojamiento ideal","Compara precios, servicios y valoraciones de cientos de hoteles en un solo lugar."],t.w)
B.ajc=new A.V(B.ag,["Filtros avanzados","Usa los filtros de precio, estrellas y servicios para afinar tu b\xfasqueda y encontrar exactamente lo que necesitas."],t.w)
B.a7n=s([B.aiX,B.ajc],t.J)
B.aj1=new A.V(B.ag,["Gestiona tus reservas","Aqu\xed puedes consultar el estado de todas tus reservas activas, pasadas y canceladas."],t.w)
B.aja=new A.V(B.ag,["Cancelaci\xf3n y modificaci\xf3n","Si necesitas cancelar o modificar una reserva, puedes hacerlo desde esta secci\xf3n hasta 24 horas antes del check-in."],t.w)
B.a7q=s([B.aj1,B.aja],t.J)
B.aj0=new A.V(B.ag,["Tus hoteles favoritos","Guarda los hoteles que m\xe1s te gusten para compararlos y reservarlos cuando quieras."],t.w)
B.aj2=new A.V(B.ag,["Sincronizaci\xf3n autom\xe1tica","Tus favoritos se sincronizan autom\xe1ticamente entre dispositivos cuando inicias sesi\xf3n."],t.w)
